inline nice_gfx::Status setMedia(View &view, Id element, const char *assetId) {
  const nice_gfx::htmlui::MediaDesc *resource = media(assetId);
  return resource ? view.setMediaResource(element, *resource) : nice_gfx::Status::InvalidArgument;
}

