inline nice_gfx::Status load(View &view) {
  const nice_gfx::Status status = view.mount(project());
  if (status == nice_gfx::Status::Ok) { view.setEdgeBackEnabled(edgeBack); view.setSwipeHomeEnabled(swipeHome); view.configureInput(inputConfig()); if (!configureUiActions(view)) return nice_gfx::Status::InvalidArgument; }
  if (status == nice_gfx::Status::Ok && !view.configureNavigation(nullptr)) return nice_gfx::Status::InvalidArgument;
  return status;
}

// Bind each action once per View. Registration is additive, including after load().
// A null callback returns false without adding listeners; callbacks/context stay user-owned.
// A false result does not roll back any earlier successful registration.
inline bool bind_zeroLevel(View &view, EventHandler callback, void *context = nullptr) {
  if (!callback) return false;
  bool ok = true;
  ok = view.on(2681804722u, nice_gfx::htmlui::EventType::Click, callback, context) && ok;
  return ok;
}
